package dev.tacticalcombat.client.ui;

import com.google.gson.*;
import java.util.*;
import static dev.tacticalcombat.client.ui.ManagementState.*;
import static dev.tacticalcombat.client.ui.DmWorkspaceModel.*;

public final class DmWorkspaceRedesignTests {
    private static int count;
    private static void check(boolean value,String reason){count++;if(!value)throw new AssertionError(reason);}
    private static JsonObject actor(String id,boolean bound,boolean eligible){return args("actor",id,"name",id,"kind","NPC","bound",bound,"eligible",eligible,"reason",eligible?"Ready":"Prepared gameplay reservation","x",1,"z",1);}
    private static JsonObject snapshot(String token,JsonObject... rows){var list=new JsonArray();for(var row:rows)list.add(row);return args("campaign","campaign","actors",list,"discovery",token,"truncated",false);}
    public static void run(){
        var m=new DmWorkspaceModel();m.campaign("campaign");
        for(var tab:List.of(Tab.ACTORS,Tab.ENCOUNTERS,Tab.SCENE)){m.tab(tab);check(m.binding.equals("BOUND")&&m.kind.equals("ALL"),"initial bound-first on each nearby tab");check(m.discovery().args().equals(args("binding","BOUND","kind","ALL")),"real read arguments use Bound");}
        m.tab(Tab.ACTORS);var a=actor("Husk",true,true);var b=actor("Player",true,true);var bat=actor("Bat",false,false);
        var query=m.discovery();var bound=snapshot("bound",a,b);check(m.applyDiscovery(query,bound),"matching authorized discovery applied");m.toggle(a);m.toggle(b);check(m.startable(bound),"two current ready actors can be reviewed for start");
        var selection=new ArrayList<>(m.participants);m.binding="UNBOUND";var unboundQuery=m.discovery();check(!m.startable(bound)&&m.discoveryToken.isEmpty(),"filter switch immediately invalidates executable old token");
        check(unboundQuery.args().get("binding").getAsString().equals("UNBOUND"),"Unbound requires fresh server read");var unbound=snapshot("unbound",bat);m.applyDiscovery(unboundQuery,unbound);check(m.participants.size()==2&&!m.startable(unbound),"retain hidden participant intentions, disable execution outside snapshot");
        m.binding="ALL";var allQuery=m.discovery();check(allQuery.args().get("binding").getAsString().equals("ALL"),"All is also fresh discovery");check(!m.applyDiscovery(unboundQuery,unbound),"delayed old filtered response cannot replace new request");
        m.binding="BOUND";var back=m.discovery();check(m.applyDiscovery(back,snapshot("newBound",b,a))&&m.startable(snapshot("newBound",b,a)),"returning to Bound validates retained selection with new token");check(new ArrayList<>(m.participants).equals(selection),"discovery order never reorders placement slots");
        m.sort="DISTANCE";m.queries.put(m.tab,"Husk");m.filter(bound.getAsJsonArray("actors"),"actor");check(new ArrayList<>(m.participants).equals(selection),"search/sort never changes selected UUID order");
        var bad=snapshot("bad",a,actor("Player",true,false));m.applyDiscovery(m.discovery(),bad);check(!m.participants.contains("Player")&&m.selectionNotice.contains("reservation"),"ineligible actor removed with server reason");
        m.toggle(b);var limited=snapshot("limited",a);limited.addProperty("truncated",true);m.applyDiscovery(m.discovery(),limited);check(m.participants.contains("Player")&&!m.startable(limited),"truncated absence is not fabricated removal or valid start");
        m.applyDiscovery(m.discovery(),snapshot("missing",a));check(!m.participants.contains("Player")&&m.selectionNotice.contains("Removed"),"missing in complete matching scope removed");
        var reboundModel=new DmWorkspaceModel();reboundModel.campaign("campaign");var oldActor=actor("same entity",true,true);oldActor.addProperty("character","first");oldActor.addProperty("characterRevision",2);var original=snapshot("original",oldActor,b);reboundModel.applyDiscovery(reboundModel.discovery(),original);reboundModel.toggle(oldActor);reboundModel.toggle(b);
        var rebound=oldActor.deepCopy();rebound.addProperty("character","second");reboundModel.applyDiscovery(reboundModel.discovery(),snapshot("rebound",rebound,b));check(!reboundModel.participants.contains("same entity")&&reboundModel.selectionNotice.contains("Associated character changed"),"same world UUID cannot silently transfer selected intent to another D&D record");
        reboundModel.toggle(rebound);var edited=rebound.deepCopy();edited.addProperty("characterRevision",3);reboundModel.applyDiscovery(reboundModel.discovery(),snapshot("edited",edited,b));check(!reboundModel.participants.contains("same entity"),"changed approved character revision requires new selection");
        var forged=snapshot("foreign",a);forged.addProperty("campaign","different");check(!m.applyDiscovery(m.discovery(),forged),"server campaign context must match captured request");
        m.kind="PLAYER";m.eligibility="READY";m.tab(Tab.SCENE);check(m.binding.equals("BOUND")&&m.kind.equals("ALL"),"Scene filters independent of Actors");m.tab(Tab.ACTORS);check(m.kind.equals("PLAYER")&&m.eligibility.equals("READY"),"per-tab filter values restored");
        var pending=m.discovery();m.campaign("newCampaign");check(!m.applyDiscovery(pending,bound)&&m.participants.isEmpty()&&m.binding.equals("BOUND")&&m.queries.isEmpty(),"campaign switch clears identities, tokens, queries and old callbacks");m.recipients.add("private");m.targets.add("private");m.revoke();check(m.recipients.isEmpty()&&m.targets.isEmpty()&&m.discoveryToken.isEmpty(),"revocation clears private choices");
        for(int n:new int[]{0,1,2,16,17,64}){var model=new DmWorkspaceModel();model.campaign("campaign");var rows=new ArrayList<JsonObject>();for(int i=0;i<n;i++)rows.add(actor("actor"+i,true,true));var current=snapshot("token",rows.toArray(JsonObject[]::new));model.applyDiscovery(model.discovery(),current);for(var row:rows)model.toggle(row);check(model.participants.size()==Math.min(16,n),"selection has hard cap16");check(model.startable(current)==(n>=2),"start requires at least2, cap16");model.invalidateDiscovery();check(!model.startable(current),"read invalidation blocks Start");}
        check(empty("BOUND",false).contains("Unbound")&&empty("UNBOUND",false).contains("snapshot")&&empty("BOUND",true).contains("filters"),"honest empty-state guidance");
        for(int width:new int[]{320,426,480,640,854,960,1280,1920})for(int height:new int[]{180,240,270,360,540,720,1080})for(boolean compact:List.of(true,false))for(var tab:Tab.values()){
            var layout=layout(width,height,compact,tab);check(layout.frame().fits(width,height)&&layout.body().fits(width,height),"all tab layouts bounded");check(layout.body().y()+layout.body().height()<=layout.frame().y()+layout.frame().height()-30,"content leaves safe footer");
            int w=layout.body().width()-16;var c=WorkspaceRosterRow.columns(w,true);check(c.nameX()+c.nameWidth()<=c.checkboxX()&&c.checkboxX()+24<=w,"name and checkbox columns never overlap");if(c.statusWidth()>0)check(c.nameX()+c.nameWidth()<=c.statusX()&&c.statusX()+c.statusWidth()<=c.checkboxX(),"wide status column disjoint");check(c.nameWidth()>=100,"primary names have readable width");
        }
        check(layout(854,480,true,Tab.ROLLS).body().height()>layout(854,480,true,Tab.ACTORS).body().height(),"Rolls has no irrelevant actor filter header");check(WorkspaceRosterRow.HEIGHT<=30,"dense roster replaces >100px actor cards");
        for(int size:new int[]{120,160,190,240})for(double x:new double[]{-32,-16,0,16,32}){double mapped=WorkspaceSceneMap.coordinate(x,0,size);check(mapped>=16&&mapped<=size-16,"map markers bounded");check(WorkspaceSceneMap.coordinate(x,0,size)<WorkspaceSceneMap.coordinate(x+1,0,size)||x==32,"map direction monotonic");}
        check(WorkspaceSceneMap.coordinate(-16,0,190)<WorkspaceSceneMap.coordinate(16,0,190),"North/negative Z maps upward");check(!WorkspaceSceneMap.mappable(args("x",33,"z",0),0,0)&&!WorkspaceSceneMap.mappable(args("x",Double.NaN,"z",0),0,0),"off-area/invalid markers not invented");
        var result=args("source","DM_REQUEST","mode","DISADVANTAGE","faces",JsonParser.parseString("[19,4]"),"kept",JsonParser.parseString("[1]"),"total",6);check(roll(result).contains("kept 4")&&!roll(result).contains("DC"),"kept face follows server indices without guessing result or hidden DC");result.addProperty("dc",8);result.addProperty("success",false);check(roll(result).contains("Failure"),"only supplied authorized outcome shown");
        var gate=new WorkspaceMutationGate();var ticket=gate.begin("campaign");check(gate.pending()&&gate.begin("campaign")==null,"one explicit mutation pending; double dispatch blocked");
        // Geometry/form rebuilds change no operation state.
        for(int size:new int[]{320,426,854,1920}){layout(size,240,true,Tab.ROLLS);check(gate.matches(ticket,"campaign"),"resize preserves accepted/prepared operation lifetime");}
        check(!gate.matches(ticket,"other"),"campaign scope blocks delayed operation callback");check(gate.complete(ticket,"campaign")&&!gate.complete(ticket,"campaign"),"matching reply settles exactly once");
        var stale=gate.begin("campaign");gate.invalidate();var next=gate.begin("campaign");check(!gate.matches(stale,"campaign")&&gate.matches(next,"campaign"),"revocation/close invalidate old pending identity without releasing new one");
        var sent=new ArrayList<dev.tacticalcombat.uiapi.UiApiService.Operation>();var callbacks=new ArrayList<java.util.function.Consumer<dev.tacticalcombat.uiapi.UiApiService.Reply>>();var accepted=new java.util.concurrent.atomic.AtomicInteger();
        var pump=new UiRequestPump(new UiRequestPump.Transport(){public boolean supported(){return true;}public void send(dev.tacticalcombat.uiapi.UiApiService.Operation op,JsonObject args,java.util.function.Consumer<dev.tacticalcombat.uiapi.UiApiService.Reply> reply){sent.add(op);callbacks.add(reply);}});
        gate.invalidate();var prepared=gate.begin("campaign");pump.enqueue(dev.tacticalcombat.uiapi.UiApiService.Operation.CHECK_PREPARE,new JsonObject(),()->gate.matches(prepared,"campaign"),reply->{if(gate.complete(prepared,"campaign"))accepted.incrementAndGet();});pump.tick();layout(426,240,true,Tab.ROLLS);callbacks.getLast().accept(new dev.tacticalcombat.uiapi.UiApiService.Reply("OK","prepared",args("operation","id")));check(accepted.get()==1,"actual UI pump retains explicit preparation acknowledgement through layout rebuild");
        for(int frame=0;frame<100;frame++){layout(854,480,true,Tab.ROLLS);pump.tick();}check(sent.equals(List.of(dev.tacticalcombat.uiapi.UiApiService.Operation.CHECK_PREPARE)),"rebuild/render loop cannot execute or repeat prepared check");
        System.out.println("DM workspace redesign tests passed: "+count);
    }
}
